fn solve(a: i8, b: i8) -> (i8, i8) {
    // To avoid overflow when adding/subtracting two i8 values,
    // cast to i16 first.
    let a16 = a as i16;
    let b16 = b as i16;

    // Given:
    //   a = x + y
    //   b = x - y
    // We solve for x, y:
    //   x = (a + b) / 2
    //   y = (a - b) / 2
    //
    // The problem guarantees that a and b have the same parity,
    // so (a + b) and (a - b) are even, and the division yields integers.

    let x16 = (a16 + b16) / 2;
    let y16 = (a16 - b16) / 2;

    // Now cast back to i8. Under the problem constraints,
    // x16 and y16 will lie within [-100, 100], so this is safe.
    let x = x16 as i8;
    let y = y16 as i8;

    (x, y)
}

